cd <trial> && mkdir -p work && cat > work/find.py <<'EOF'
import ast, sys
path = sys.argv[1]
src = open(path, encoding="utf-8").read()
lines = src.splitlines()
tree = ast.parse(src)
classes = {n.name: n for n in tree.body if isinstance(n, ast.ClassDef)}
def methods(cls):
    out = []
    for n in cls.body:
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out.append((n.name, n.lineno))
    return out
c = {name for name, _ in methods(classes["Client"])}
a = methods(classes["AsyncClient"])
for name, ln in a:
    if name not in c:
        print(f"httpx/_client.py:{ln}: {lines[ln-1].strip()}")
print("AsyncClient methods:", len(a), file=sys.stderr)
EOF
